# -*- coding: utf-8 -*-
from pathlib import Path
import json,html
B=Path(__file__).resolve().parents[1];A='/assets/studies/sceye-haps/stage-05';NATIVE='https://github.com/mrkhani88/khani-solutions-site/releases/download/haps-stage05-cold-startup-r1';e=html.escape
S=json.loads((B/'results/summary.json').read_text());C={c['id']:c for c in S};m=C['managed']['windows']['startup'];d=C['cold_delay']['windows']['startup'];ref=C['reference']['windows']['startup'];settled=C['managed']['windows']['settled'];stress=C['stress']['windows']['settled'];balanced=C['stress_balanced']['windows']['settled'];R=json.loads((B/'verification/refinement.json').read_text());N=json.loads((B/'verification/stage04-reproduction.json').read_text());probes=json.loads((B/'verification/analytical-delay-probes.json').read_text())
rows=''
for c in S:
 w=c['windows']['startup'];acq='Warm start' if w['acquire_10min_band_minutes'] is None else f"{w['acquire_10min_band_minutes']:.1f}"
 rows+=f"<tr><th>{e(c['title'])}</th><td>{w['initial_housing_C']:.1f}</td><td>{acq}</td><td>{w['peak_heater_W']:.1f}</td><td>{w['hours_near_hardware_cap']:.3f}</td><td>{w['hours_at_command_ceiling']:.3f}</td><td>{w['motor_energy_kWh']:.3f}</td><td>{w['all_heater_energy_kWh']:.3f}</td><td>{w['DC_energy_kWh']:.3f}</td></tr>"
settledrows=''
for id in ['reference','cold_delay','managed','stress','stress_managed','stress_tuned','stress_balanced']:
 c=C[id];w=c['windows']['settled'];settledrows+=f"<tr><th>{e(c['title'])}</th><td>{w['min_housing_C']:.3f}</td><td>{w['peak_heater_W']:.1f}</td><td>{w['heater_on_max_abs_error_K']:.3f}</td><td>{w['all_heater_energy_kWh']:.3f}</td><td>{'Within chosen band' if w['heater_on_max_abs_error_K']<=.5 else 'Exceeds chosen band'}</td></tr>"
nodeoptions=''.join(f'<option value="{key}">{name}</option>' for key,name in [('propulsion.housing','Motor housing / heater location'),('propulsion.winding','Motor winding'),('propulsion.controller','Motor drive electronics / ESC'),('propulsion.bracket','Motor bracket'),('avionics.cpu','Processor aggregate'),('battery.core','Battery core'),('payload.rf','RF payload aggregate')])
maxref=max(v for win in R['differences'].values() for k,v in win.items() if k in [n['key'] for n in json.loads((B/'inputs/component-nodes.json').read_text())])
body=f'''<div class="haps wrap" id="haps-startup" data-base="{A}">
<section id="cold-startup"><p class="eyebrow">Stage 05 / Cold-soaked startup · sensor and heater dynamics</p><h2>Cold start, realistic response models and a reserved heater margin.</h2><p>The Stage 04 controller worked from a warm initial motor. Starting its winding, housing, drive electronics and bracket at −40°C exposes the warm-up energy and power limits. The delayed case reaches the −5±0.5°C band in <b>{d['acquire_10min_band_minutes']:.1f} minutes</b>, but spends <b>{d['hours_near_hardware_cap']:.2f} hours near the 300 W hardware limit</b>. A deliberate 270 W command ceiling retains 30 W of hardware reserve and reaches the band in <b>{m['acquire_10min_band_minutes']:.1f} minutes</b>.</p><div class="haps-jump"><a href="#startup-inputs">1 · Cold states and delay assumptions</a><a href="#startup-method">2 · Heat/control chain</a><a href="#startup-explorer">3 · Interactive comparison</a><a href="#startup-results">4 · Temperatures and energy</a><a href="#startup-checks">5 · Checks and limits</a><a href="#startup-downloads">6 · Source and native data</a><a href="#motor-control">Previous Stage 04</a></div><p class="h5-warning"><b>A modeled cold-start test, with declared hardware assumptions.</b> The selected sensor, heater mounting and motor/ESC cold-operating limits are not yet known. The time constants below are engineering test scenarios, not measured Sceye specifications. The 270 W case reaches its <b>software ceiling</b> during warm-up; reserving 30 W does not remove saturation or prove fault recovery. The controlled variable is motor-housing heater temperature; the ESC remains a separate thermal node.</p></section>
<section id="startup-inputs"><p class="eyebrow">01 / Define the starting condition before comparing controllers</p><h2>What is cold, what is delayed, and what stays fixed?</h2><div class="h5-scroll" tabindex="0" role="region" aria-label="Cold-start design assumptions"><table><thead><tr><th>Input</th><th>Stage 04 reference</th><th>New startup / nominal delays</th><th>Stress / interpretation</th></tr></thead><tbody><tr><th>Motor assembly initial temperature</th><td>20°C</td><td>−40°C: winding, housing, ESC and bracket</td><td>Separate −50°C motor case. Sensor starts at the same temperature. Integral correction starts at zero. Delayed cases start at0W; the ideal bypass applies300W immediately.</td></tr><tr><th>Other 20 thermal nodes</th><td>Original Stage 04 initial states</td><td>Same original states, isolating motor soak</td><td>Separate entire-network case starts all 24 masses at −40°C. Battery SOC remains 70%. This is not an equilibrium soak calculation.</td></tr><tr><th>Heater and target</th><td>300 W installed; −5°C housing heating floor</td><td>Same hardware and chosen ±0.5 K band</td><td>270 W ceiling preserves 10% installed-power reserve; limits come from this study, not a part datasheet.</td></tr><tr><th>Sensor response</th><td>Direct housing temperature</td><td>First-order time constant 30 s</td><td>120 s stress case. No bias, noise, placement error or sensor fault. Mounted response must be measured.</td></tr><tr><th>Command transport delay</th><td>0 s</td><td>2 s pure dead time; pre-start command history is zero</td><td>10 s stress case. A chosen electronics/communications budget, not a measured device response.</td></tr><tr><th>Delivered electrical-power response</th><td>Instantaneous averaged power</td><td>First-order time constant 5 s, initially 0 W</td><td>30 s stress case. Output/actuator approximation; no separate heater-film thermal mass or PWM is resolved.</td></tr><tr><th>PI tuning</th><td>Kp=300 W/K; Ki=2 W/(K·s)</td><td>Same gains; anti-windup tracking 60 s</td><td>Combined slow case also tests Kp=200, Ki=0.5 then 0.75 (Ti=266.7 s for the balanced candidate). These are tested gains, not a universal optimum.</td></tr><tr><th>Environment and loads</th><td>Prescribed 20 km day/night cycle</td><td>Same wind, solar/IR, thermal paths, capacities and electrical loss maps</td><td>Combined stress lowers air by 10 K while retaining IR/wind/load profiles. Motor and electronics loads remain enabled from t=0; no cold-start operation interlock is modeled.</td></tr><tr><th>Time / energy comparison</th><td>First 24 h reproduced, plus settled day 08</td><td>Same two windows for every case</td><td>No daily controller reset. First-day startup energy is not subtracted from a settled-day baseline.</td></tr></tbody></table></div><p class="haps-small">The ideal-response cold case applies300W immediately; its zero-initialized output-filter state is bypassed. <a href="{A}/docs/Initial-Power-Clarification.txt" download>Initial-power description clarification and original-record boundary ↓</a></p><p><a href="{A}/inputs/startup-design.json" download>Complete startup assumptions ↓</a> · <a href="{A}/inputs/cases.json" download>Exact native parameter overrides ↓</a> · <a href="#night-inputs">Inherited materials, load maps and thermal paths</a></p></section>
<section id="startup-method"><p class="eyebrow">02 / Follow the energy and feedback step by step</p><h2>Why a cold start asks for more power.</h2><div class="h5-chain" aria-label="Closed-loop motor heater signal chain"><span>Housing temperature</span><b>→</b><span>Sensor lag</span><b>→</b><span>PI + command ceiling</span><b>→</b><span>Command dead time</span><b>→</b><span>Delivered-power response</span><b>→</b><span>Housing heat + DC-bus demand</span></div><ol><li><b>Warm the thermal mass.</b> The four motor-assembly capacities total 59 kJ/K. Raising all four from −40 to −5°C would store about 2.065 MJ (0.574 kWh), before accounting for concurrent motor losses, external losses and heat exchanged with the surrounding vehicle. The heater acts on the housing, so the four parts do not warm uniformly.</li><li><b>Test the existing controller honestly.</b> At startup the 35 K error requests 10.5 kW through its proportional term. The installed heater can deliver only 300 W. Anti-windup manages the integrator; it cannot supply unavailable heat. The ideal cold case and delayed cold case both spend about 2.6 h at the hardware limit.</li><li><b>Add the feedback and output dynamics.</b> Sensor temperature follows the housing gradually; the command arrives late and delivered power ramps. Their nominal few-second effect is small compared with an hours-long warm-up, but long sensor/output lags reduce damping around the target.</li><li><b>Trade warm-up time for reserve.</b> The 270 W ceiling keeps actual power 30 W below installed capacity and increases acquisition time by {m['acquire_10min_band_minutes']-d['acquire_10min_band_minutes']:.1f} min. Its slightly lower first-day heat use reflects spending longer cold, with smaller heat loss; it is not evidence of a more efficient heater.</li><li><b>Retune the combined slow-response case.</b> With the original gains, day 08 reaches {stress['peak_heater_W']:.1f} W and the maximum heater-on true-temperature error is {stress['heater_on_max_abs_error_K']:.3f} K, outside the chosen band. Reducing gains damps the night oscillation; Ki=0.5 leaves a larger warm-transition error. The Kp=200 / Ki=0.75 candidate brings the day 08 peak to {balanced['peak_heater_W']:.1f} W and heater-on maximum error to {balanced['heater_on_max_abs_error_K']:.3f} K. Inspect both the startup and settled windows before selecting a controller.</li><li><b>Account for the whole system.</b> Delivered heater power enters the motor housing and the common DC demand. Changed converter/battery losses feed back into the integrated 24-node thermal network. Cold battery charging permission remains active in the entire-network sensitivity, but prescribed hardware loads are not proven operable at −40°C.</li></ol><div class="h5-equations">τsensor · dTsensor/dt = Thousing − Tsensor<br>e = −5°C − Tsensor; u = Kp·e + I<br>Pcommand = clip(u, 0, min(Pinstalled, Pceiling))<br>dI/dt = Ki·e + (Pcommand − u)/60 s<br>Pdelayed = 0 before startup + dead time; then Pcommand(t − dead time)<br>τheater · dPdelivered/dt = Pdelayed − Pdelivered<br>Qhousing,heater = Pdelivered; DC demand includes Pdelivered</div><p class="haps-small">Zero-time-constant cases bypass the corresponding lag. Anti-windup tracks the limited command; it does not cancel sensor or actuator dynamics. General formulations: <a href="https://doc.modelica.org/om/Modelica.Blocks.Continuous.LimPID.html">limited PI</a>, <a href="https://doc.modelica.org/om/Modelica.Blocks.Continuous.FirstOrder.html">first-order response</a>, <a href="https://doc.modelica.org/om/Modelica.Blocks.Nonlinear.FixedDelay.html">fixed delay</a>. These method references do not supply the chosen hardware time constants.</p></section>
<section id="startup-explorer"><p class="eyebrow">03 / Inspect native solved histories</p><h2>Watch warm-up, lag and heater reserve on the same clock.</h2><div class="haps-box"><div class="h5-controls"><label>Startup / controller case<select id="h5-case" aria-label="Cold startup case"><option>Loading native data…</option></select></label><label>Comparison window<select id="h5-window" aria-label="Startup or settled window"><option value="startup">First day / cold startup</option><option value="settled">Settled day 08</option></select></label><label>Chart extent<select id="h5-range" aria-label="Startup chart hours"><option value="6">First 6 hours</option><option value="1">First hour</option><option value="24">Full 24 hours</option></select></label><label>Temperature component<select id="h5-node" aria-label="Startup component">{nodeoptions}</select></label></div><label><input type="checkbox" id="h5-overlay" checked> Overlay paired comparison cases</label><p id="h5-note" aria-live="polite">Loading saved results…</p><div id="h5-stats" class="h5-stats"></div><div class="h5-time"><button id="h5-play">Play</button><input id="h5-time" type="range" min="0" max="2160" value="0" aria-label="Cold startup time"><output id="h5-time-text">00:00:00</output></div><div id="h5-now"></div><div class="h5-tabs" role="group" aria-label="Cold startup plot">{''.join(f'<button data-h5-plot="{key}" aria-pressed="{str(key=="temperature").lower()}">{label}</button>' for key,label in [('temperature','Temperature'),('power','Command / delivered power'),('motorEnergy','Motor heater energy'),('allEnergy','All heater energy'),('error','Signed target error'),('soc','Battery SOC')])}</div><label id="h5-zoom-label"><input type="checkbox" id="h5-zoom"> Zoom to the target band (clips cold startup)</label><div id="h5-chart"></div><div id="h5-legend"></div><p id="h5-chart-note" class="haps-small"></p><p id="h5-performance" class="haps-small"></p><a id="h5-csv" href="{A}/results/managed_startup.csv" download>Download selected first-day CSV ↓</a></div></section>
<section id="startup-results"><p class="eyebrow">04 / Compare like-for-like time windows</p><h2>First-day warm-up and the ongoing night-control cost.</h2><p><b>Nominal delayed cold start → reserved-power startup:</b> band acquisition {d['acquire_10min_band_minutes']:.1f}→{m['acquire_10min_band_minutes']:.1f} min; motor-heater energy {d['motor_energy_kWh']:.3f}→{m['motor_energy_kWh']:.3f} kWh in the first 24 h; all-heater energy {d['all_heater_energy_kWh']:.3f}→{m['all_heater_energy_kWh']:.3f} kWh. Compared with the same-window Stage04 warm start ({ref['all_heater_energy_kWh']:.3f} kWh), the managed cold start adds {m['all_heater_energy_kWh']-ref['all_heater_energy_kWh']:.3f} kWh of all-heater energy.</p><div class="h5-scroll" tabindex="0" role="region" aria-label="First-day cold-start results"><table><thead><tr><th>Case / first 24 h</th><th>Initial housing °C</th><th>10-min band acquisition min</th><th>Peak motor heater W</th><th>Near300 W limit h</th><th>At command ceiling h</th><th>Motor heat kWh</th><th>All heat kWh</th><th>Total DC kWh</th></tr></thead><tbody>{rows}</tbody></table></div><p class="haps-small">Hardware-near-limit means delivered power≥297W (99% of 300 W); command-ceiling time means command≥99.9% of its own ceiling. Acquisition is first entry to−5±0.5°C sustained for 10 min, not a promise to stay at−5°C throughout warm daytime operation. Native floating-point power overshoots below 0.001 W are treated as numerical tolerance, not extra physical capacity.</p><h3>Settled day 08</h3><p>After nominal cold-start transients settle, the managed case returns to {settled['peak_heater_W']:.1f} W peak heater demand and {settled['all_heater_energy_kWh']:.3f} kWh/day all-heater energy, essentially the prior Stage04 mission. The cold-start penalty is transient. The combined colder/slow-response case changes both the environment and control dynamics, so compare its own gain/ceiling variants to isolate the controller effect.</p><div class="h5-scroll" tabindex="0" role="region" aria-label="Settled-day controller comparison"><table><thead><tr><th>Case / day 08</th><th>Housing minimum °C</th><th>Peak heater W</th><th>Maximum heater-on true error K</th><th>All heater kWh/day</th><th>Chosen ±0.5K criterion</th></tr></thead><tbody>{settledrows}</tbody></table></div><p class="h5-warning"><b>Startup cannot satisfy the temperature band from t=0.</b> It begins35K below target by definition. Use acquisition time for warm-up and heater-on tracking for settled operation. The entire-network −40°C sensitivity uses {C['full_soak']['windows']['startup']['all_heater_energy_kWh']:.3f} kWh of first-day all-heater energy; this larger battery/payload/structure warm-up burden does not establish that those parts can operate cold.</p></section>
<section id="startup-checks"><p class="eyebrow">05 / Numerical evidence and remaining physical tests</p><h2>Check the coupled model before interpreting performance.</h2><ul><li>All {len(S)} native mission cases plus a managed-startup refinement completed8 continuous days with finite data, bounded SOC, thermal/whole-system energy checks and final-cycle repeatability.</li><li>Warm-start reference reproduces the saved Stage04 selected PI across all 24 node temperatures within {N['max_difference_K']:.6f}K.</li><li>Maximum integration step2s / tolerance1e−7 versus0.5s /1e−8 changes exported node temperatures by at most {maxref:.6f}K; source/refinement comparisons are downloadable.</li><li>Separate analytical fixtures verify a 300 W step after2 s dead time with5 s first-order response, and a 30 s sensor response. Maximum analytical errors: {probes['checks']['Actuator']['analytical_max_error']:.2e}W and {probes['checks']['Sensor']['analytical_max_error']:.2e}K.</li><li>Thermal capacities, material paths, surfaces, native connections and mission electrical loss maps remain unchanged. Only initial motor/network temperatures and the explicitly listed control/environment overrides vary.</li></ul><p><b>Next physical-data gate:</b> measure mounted sensor/heater response, determine heater electrical limits versus bus voltage and cold resistance, select motor/ESC/battery allowables, add temperature-dependent loss maps and cold-start permissives, then correlate warm-up and cycling tests. Sensor bias/noise/failure, heater fail-on/off, transport jitter, PWM and spatial heater/contact hot spots remain unresolved. The assumed 59kJ/K motor assembly should be replaced by a mass/material heat-capacity budget.</p><p><a href="{A}/verification/numerical-audit.json" download>Conservation / controls audit ↓</a> · <a href="{A}/verification/refinement.json" download>Time-step refinement ↓</a> · <a href="{A}/verification/analytical-delay-probes.json" download>Analytical response checks ↓</a></p></section>
<section id="startup-downloads"><p class="eyebrow">06 / Reproduce or inspect the evidence</p><h2>Download the model, startup inputs and native histories.</h2><div class="h5-downloads"><a href="{A}/{B.name}.zip" download>Complete source + inputs + browser data + CSV/audit bundle ↓</a><a href="{A}/source/HAPSDiurnal.mo" download>Native hierarchical OpenModelica model ↓</a><a href="{A}/docs/Results-Walkthrough.txt" download>Step-by-step results walkthrough ↓</a><a href="{A}/manifest.json" download>File hashes and separate native archives ↓</a><a href="{A}/inputs/startup-design.json" download>Initialization, delay assumptions and criteria ↓</a><a href="{A}/results/summary.json" download>All case/window temperature and energy metrics ↓</a></div><details><summary>Full 8-day native records for each case</summary><p>Each separate archive contains the full native solver CSV, solver log, source model and exact run record. These large archives are hosted as GitHub release downloads, separate from the compact source/browser bundle and website assets.</p><div class="h5-downloads">{''.join(f'<a href="{NATIVE}/{c["id"]}-full-native.zip" download>{e(c["title"])} · full native record ↓</a>' for c in S)}<a href="{NATIVE}/managed_fine-full-native.zip" download>Managed startup · numerical refinement native record ↓</a></div></details><p><a href="#motor-downloads">Stage04 controller study downloads</a> · <a href="#night-downloads">Stage03 spatial electronics and CAD downloads</a> · <a href="#downloads">Original vehicle CAD and evidence downloads</a></p><p class="haps-small">Independent public-reference engineering study, not Sceye product data or manufacturer validation. No employer/client material is used.</p></section></div>'''
(B/'source/stage-body.html').write_text(body)
(B/'Review.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HAPS cold startup / Stage05</title><link rel="stylesheet" href="review.css"><link rel="stylesheet" href="source/startup.css"><body>'+body.replace(A,'.')+'<script type="module" src="source/startup.mjs"></script></body></html>')
